; Reset the game variables for a new game or demo. Called by restart_to_title, start_attract_demo and
; start_new_game. Changes A, X, Y.
; - Clears zero page $03-$F5 (current_player ... room, score, all actor fields) and the workspace
;   $4EED-$4FE7 (contact_col0 ... burst_trap_row).
; - Sets $0100-$0107 (text_single_height, the flame timers, game_mode = 1, pause_state, actor_step_delay)
;   and the room13_band_bonus flags to 1; silences the sound.
; - extra_fall_pickups_left = 5 for both players; room_lanterns_left from room_lantern_count_init; all rooms
;   but room 0 unvisited for both players (room_unvisited); every lantern present (reset_all_lanterns,
;   fill_parked_lanterns).
; - falls_left = 4 (9 when player 2 controls Yamo); bonus_fall_next_score of both players =
;   bonus_fall_first_score (40000).
; - Copies the player block $28-$43 (falls_left ... score) to inactive_player_state, the parked block of
;   player 2.
init_game_variables
        lda #$00                        ; A = 0, X = 0
        tax
init_game_clear_loop
        cpx #$f3                        ; X < $F3: clear $03-$F5
        bcs init_game_clear_4eed
        sta current_player,x
init_game_clear_4eed
        cpx #$fb                        ; X < $FB: clear $4EED-$4FE7
        bcs init_game_clear_next
        sta contact_col0,x
init_game_clear_next
        inx
        bne init_game_clear_loop
        sta yamo_idle_time              ; yamo_idle_time = 0 (already cleared by the loop)
        sta yamo_idle_time+1
        ldx #$07
        lda #$01
init_game_flags_loop
        sta room13_band_bonus,x         ; $014B-$0152: room 13 band bonus flags of both players
        sta text_single_height,x        ; $0100-$0107: game_mode = 1 (game)
        dex
        bpl init_game_flags_loop
        jsr stop_all_sounds             ; silence all sound
        lda #$05
        sta extra_fall_pickups_left     ; 5 extra-fall pickups for player 1 ...
        sta extra_fall_pickups_left+1   ; ... and for player 2
        jsr reset_lantern_counts        ; lantern counts of all rooms
; Rooms not yet visited: one byte per room and player at room_unvisited + room*2 + player.
        ldx #$27
        lda #$01
init_game_room_flags_loop
        sta room_unvisited,x
        dex
        bpl init_game_room_flags_loop
        lda #$00                        ; room 0 counts as visited for both players
        sta room_unvisited
        sta room_unvisited+1
        jsr reset_all_lanterns          ; set every lantern of every room present
        jsr fill_parked_lanterns
        lda #$04                        ; 4 falls
        sta falls_left
        lda option_yamo_player2
        beq init_game_copy_scores
; not executed $0fc5-$0fc8
        lda #$09                        ; 9 falls when Yamo is player controlled
        sta falls_left
; bonus_fall_next_score of both players = bonus_fall_first_score (40000 points).
init_game_copy_scores
        ldx #$02
init_game_score_loop
        lda bonus_fall_first_score,x
        sta bonus_fall_next_score,x
        sta bonus_fall_next_score_other,x
        dex
        bpl init_game_score_loop
        ldx #$1b                        ; 28 bytes: falls_left ($28) to score+2 ($43)
init_game_park_player_loop
        lda falls_left,x
        sta inactive_player_state,x
        dex
        bpl init_game_park_player_loop
        rts
; Set the 97 parked_lantern_flags ($0340-$03A0) to 1 (every lantern present). The parked copy holds the
; lanterns of the player who is not playing in a two-player game. Called by init_game_variables. Changes A, X.
fill_parked_lanterns
        lda #$01
        ldx #$60
fill_parked_lanterns_loop
        sta parked_lantern_flags,x
        dex
        bpl fill_parked_lanterns_loop
        rts
; Two-player game: exchange the lantern states of all 20 rooms with parked_lantern_flags. For each room it
; walks the lantern list of the room (lantern_list_ptr, 4-byte records, end at a byte with bit 7 set) and
; swaps byte 0 of each record with the next parked flag. row_ptr_top = parked flag pointer, aux_ptr = record
; pointer, next_room = room loop counter. Called by lose_fall (next_turn_enter_room) when the turn passes to
; the other player.
swap_player_lanterns
; not executed $0fed-$104a
        lda #<parked_lantern_flags      ; row_ptr_top = parked_lantern_flags
        sta row_ptr_top
        lda #>parked_lantern_flags
        sta row_ptr_top+1
        lda #$00
        sta next_room
swap_player_lanterns_loop
        asl
        tax
        jsr swap_room_lanterns
        inc next_room
        lda next_room
        cmp #$14                        ; 20 rooms
        bcc swap_player_lanterns_loop
        rts
; Swap byte 0 of each record of one room lantern list with the parked flags. Input: X = room * 2,
; row_ptr_top = next parked flag (advanced by one per record).
swap_room_lanterns
        lda lantern_list_ptr,x
        sta aux_ptr
        lda lantern_list_ptr+1,x
        sta aux_ptr+1
        ldy #$00
swap_room_lanterns_loop
        lda (aux_ptr),y
        bmi swap_room_lanterns_done     ; bit 7: end of the list
        pha
        lda (row_ptr_top),y
        tax
        pla
        sta (row_ptr_top),y
        txa
        sta (aux_ptr),y
        jsr advance_aux_ptr_by_4        ; next record (+4)
        jsr inc_pointer_04_copy         ; next parked flag
        jmp swap_room_lanterns_loop
swap_room_lanterns_done
        rts
; Start the screen saver: save the 20 bytes of room_band_colours in palette_backup and set idle_timer to $FE
; (bit 7 set = saver running). frame_update then flashes the band colours. Called by frame_update when
; idle_timer reaches $80 (32768 frames without input).
start_screen_saver
        ldx #$13
start_screen_saver_loop
        lda room_band_colours,x
        sta palette_backup,x
        dex
        bpl start_screen_saver_loop
        lda #$fe
        sta idle_timer
        rts
; End the screen saver: restore room_band_colours from palette_backup and set idle_timer to 0. Called by
; toggle_pause when the game leaves the pause.
stop_screen_saver
        ldx #$13
stop_screen_saver_loop
        lda palette_backup,x
        sta room_band_colours,x
        dex
        bpl stop_screen_saver_loop
        lda #$00
        sta idle_timer
        rts
; Move the floor movers of room 13 (room13_frame): slots 8..0 (slot 9 is never processed), each a runner
; that runs along a text row and wraps around at the ends of its span. Per slot x:
; mover_dir 0 = inactive, bit 7 clear = moves left, bit 7 set = moves right; mover_col = column;
; mover_row = text row; mover_old_col = previous column; mover_min_col = lowest column; mover_wrap_col =
; highest column. Each active slot moves one column (a left mover below mover_min_col restarts at
; mover_wrap_col, a right mover at mover_wrap_col restarts at mover_min_col), then draw_runner_step (rows 5
; and 10: draw_runner_step_alt) redraws the old column as track and draws the runner at the new one.
; runner_col, runner_row and runner_old_col pass the positions to the draw routines. Changes A, X, Y.
update_floor_movers
        ldx #$08
update_floor_movers_loop
        lda mover_dir,x
        beq update_floor_movers_next    ; inactive object
        txa
        pha
        lda mover_col,x
        sta mover_old_col,x
        sta runner_old_col
        lda mover_row,x
        sta runner_row
        lda mover_dir,x
        bmi update_floor_movers_right   ; bit 7: moving right
        dec mover_col,x
        lda mover_col,x
        cmp mover_min_col,x
        bcs update_floor_movers_draw
        lda mover_wrap_col,x
        sta mover_col,x
update_floor_movers_draw
        sta runner_col
        lda runner_row
        cmp #$05                        ; rows 5 and 10 use the other glyphs
        beq update_floor_movers_draw_alt
        cmp #$0a
        beq update_floor_movers_draw_alt
        jsr draw_runner_step
        jmp update_floor_movers_restore_x
update_floor_movers_draw_alt
        jsr draw_runner_step_alt
        jmp update_floor_movers_restore_x
update_floor_movers_right
        inc mover_col,x
        lda mover_col,x
        cmp mover_wrap_col,x
        bcc update_floor_movers_draw_right ; at the wrap column: back to the lowest column
        lda mover_min_col,x
        sta mover_col,x
update_floor_movers_draw_right
        sta runner_col
        lda runner_row
        cmp #$05
        beq update_floor_movers_draw_alt
        cmp #$0a
        beq update_floor_movers_draw_alt
        jsr draw_runner_step
update_floor_movers_restore_x
        pla
        tax
update_floor_movers_next
        dex
        bpl update_floor_movers_loop
        rts
